//! Turning a shorthand into the longhands Chrome stores, and turning them back.
//!
//! Chrome does not keep a shorthand in a declaration: `border: 1px solid red`
//! is seventeen entries, `style.length` is 17, and every read of `border` --
//! `getPropertyValue`, `cssText`, a style map -- is rebuilt from those
//! seventeen. The measurements behind the two directions are in
//! chrome_shorthands.zig, generated by tools/fingerprint/dump-css-shorthands.mjs.
//!
//! Everything here is table-driven. A shorthand the generator could not model
//! is absent from `expand`'s answer, and the caller keeps the declaration
//! whole -- one entry where Chrome has nine, which is a visible difference but
//! a smaller one than nine invented values.
const std = @import("std");

const table = @import("chrome_shorthands.zig");
const chrome_bounds = @import("chrome_bounds.zig");
const chrome_keywords = @import("chrome_keywords.zig");
const chrome_units = @import("chrome_units.zig");
const chrome_initial_values = @import("chrome_initial_values.zig");

const Allocator = std.mem.Allocator;

pub const Shorthand = table.Shorthand;

/// The longhands a shorthand became, parallel arrays in the order `item(i)`
/// answers.
pub const Expansion = struct {
    names: []const []const u8,
    values: []const []const u8,
};

/// The entry for a name this engine expands, or null for a longhand, an unknown
/// name, or a shorthand the generator left `.unmodelled`.
pub fn lookup(name: []const u8) ?Shorthand {
    const entry = table.shorthands.get(name) orelse return null;
    if (entry.kind == .unmodelled) return null;
    return entry;
}

/// Like `lookup`, for the paths that only read a shorthand back rather than
/// store one: cssText, and the covering walk that builds it. `border-image`
/// answers here and not in `lookup`, because only half of it is modelled -- its
/// five longhands join to text Chrome writes, while a `border-image` the author
/// wrote is still kept whole rather than expanded.
pub fn lookupJoinable(name: []const u8) ?Shorthand {
    const entry = table.shorthands.get(name) orelse return null;
    if (entry.kind == .unmodelled and !isBorderImage(entry)) return null;
    return entry;
}

/// What Chrome stores for `name: value`, or null when the value does not fit
/// the shorthand's grammar. Null means "keep it whole": under-expanding leaves
/// a page working, where a wrong expansion answers values Chrome never had.
pub fn expand(arena: Allocator, entry: Shorthand, value: []const u8) !?Expansion {
    // A CSS-wide keyword reaches every longhand as itself -- and nine
    // shorthands enumerate them in a different order for that case, which is
    // why `wide_longhands` exists.
    if (cssWide(std.mem.trim(u8, value, &std.ascii.whitespace))) |keyword| {
        const names = if (entry.wide_longhands.len > 0) entry.wide_longhands else entry.longhands;
        const values = try arena.alloc([]const u8, names.len);
        @memset(values, keyword);
        return .{ .names = names, .values = values };
    }

    if (entry.kind == .layers) return layerExpand(arena, entry, value);
    if (entry.kind == .corners) return cornersExpand(arena, entry, value);

    const values = try arena.alloc([]const u8, entry.longhands.len);
    switch (entry.kind) {
        .unmodelled => return null,
        .layers, .corners => unreachable,
        .alias => values[0] = translated(entry, value),
        .presets => {
            const hit = preset(entry, value) orelse return null;
            @memcpy(values, hit[1]);
        },
        .box4, .box2 => {
            var written: [4][]const u8 = undefined;
            var count: usize = 0;
            var box = Components.init(value);
            while (box.next()) |component| : (count += 1) {
                if (count == written.len) return null;
                written[count] = component;
            }
            if (!box.exhausted()) return null;
            const mapped = boxRule(written[0..count], values.len) orelse return null;
            @memcpy(values, mapped[0..values.len]);
        },
        .components => {
            var slots: [max_group][]const u8 = undefined;
            @memset(slots[0..entry.group], "");
            var rest = Components.init(value);
            while (rest.next()) |component| {
                const slot = place(entry, component, slots[0..entry.group]) orelse return null;
                slots[slot] = component;
            }
            if (!rest.exhausted()) return null;
            for (values, 0..) |*out, i| {
                const held = if (i < entry.group * entry.groups) slots[slotOf(entry, i)] else "";
                out.* = if (held.len == 0) entry.fillers[i] else held;
            }
        },
    }
    return .{ .names = entry.longhands, .values = values };
}

/// What reading the shorthand back answers, given each longhand's stored value
/// in `entry.longhands` order. "" is a real answer, not a failure: Chrome
/// answers nothing for a `border` whose components all hold their initial
/// value, because it cannot be written as one shorthand.
pub fn join(arena: Allocator, entry: Shorthand, values: []const []const u8) ![]const u8 {
    return joinKeeping(arena, entry, values, false);
}

/// `join` with the option to write every component, whatever it holds. The
/// border family's computed serialisation does exactly that: `border` off a
/// computed view is `0px none rgb(0, 0, 0)` where the same declaration read off
/// `el.style` drops the `none`. Measured across five declaration states with
/// tools/fingerprint/scratch/expr-computed-border-join.js.
pub fn joinKeeping(arena: Allocator, entry: Shorthand, values: []const []const u8, keep_all: bool) ![]const u8 {
    std.debug.assert(values.len == entry.longhands.len);

    // Every longhand holding the same CSS-wide keyword reads back as it.
    if (cssWide(values[0])) |keyword| {
        for (values[1..]) |value| {
            if (!std.ascii.eqlIgnoreCase(value, keyword)) break;
        } else return keyword;
    }

    if (entry.kind == .layers) return layerJoin(arena, entry, values);
    if (entry.kind == .corners) return cornersJoin(arena, values);

    if (isBorderImage(entry)) return borderImageJoin(arena, values);

    switch (entry.kind) {
        .unmodelled => return "",
        .layers, .corners => unreachable,
        .alias => {
            for (entry.reads) |pair| {
                if (std.ascii.eqlIgnoreCase(pair[0], values[0])) return pair[1];
            }
            return values[0];
        },
        .presets => {
            for (entry.presets) |row| {
                for (row[1], values) |want, got| {
                    if (!std.ascii.eqlIgnoreCase(want, got)) break;
                } else return row[2];
            }
            return "";
        },
        .box4, .box2 => {
            const short = boxForm(values);
            return std.mem.join(arena, " ", short);
        },
        .components => {
            // A repeat that disagrees with the first group cannot be written as
            // one shorthand at all.
            for (0..entry.group * entry.groups) |i| {
                const mirror = representative(entry, slotOf(entry, i));
                if (!std.ascii.eqlIgnoreCase(values[i], values[mirror])) return "";
            }
            for (entry.group * entry.groups..values.len) |i| {
                if (!std.ascii.eqlIgnoreCase(values[i], entry.fillers[i])) return "";
            }

            var kept: std.ArrayList([]const u8) = .empty;
            defer kept.deinit(arena);
            for (0..entry.group) |n| {
                const slot = if (entry.order.len > 0) entry.order[n] else n;
                const held = values[representative(entry, slot)];
                if (!keep_all and dropped(entry.omit[slot], held)) continue;
                try kept.append(arena, held);
            }
            if (kept.items.len == 0) return entry.empty orelse "";
            return std.mem.join(arena, " ", kept.items);
        },
    }
}

/// The shorthands covering `name`, widest first, for putting cssText back
/// together: `border-top-width` is reachable through `border`, `border-width`
/// and `border-top`, and the widest one that has all its longhands present is
/// the one Chrome writes. A -webkit- spelling is never one of them -- Chrome
/// writes the unprefixed name.
pub fn covering(name: []const u8, buf: [][]const u8) [][]const u8 {
    var found: usize = 0;
    for (table.shorthands.keys(), table.shorthands.values()) |key, entry| {
        if (key[0] == '-') continue;
        if (entry.kind == .unmodelled and !isBorderImage(entry)) continue;
        if (entry.longhands.len == 1 and std.mem.eql(u8, entry.longhands[0], key)) continue;
        for (entry.longhands) |longhand| {
            if (!std.mem.eql(u8, longhand, name)) continue;
            if (found == buf.len) break;
            buf[found] = key;
            found += 1;
            break;
        }
    }
    const out = buf[0..found];
    std.mem.sort([]const u8, out, {}, struct {
        fn wider(_: void, a: []const u8, b: []const u8) bool {
            const left = table.shorthands.get(a).?.longhands.len;
            const right = table.shorthands.get(b).?.longhands.len;
            return if (left == right) std.mem.lessThan(u8, a, b) else left > right;
        }
    }.wider);
    return out;
}

// --- the border-image grammar -------------------------------------------
//
// `border-image` is the one shorthand with a real grammar the generator could
// not reproduce, so the table carries it as `.unmodelled`. Writing it back is
// still needed, and for two reasons rather than one: it is a covering shorthand
// of its own five longhands, and it is the last link of `border`'s fallback
// chain -- a `border` whose four widths disagree writes border-width,
// border-style, border-color and border-image instead of itself, and the chain
// is all-or-nothing.
//
// Only the joining half is modelled here. A `border-image` the author wrote
// directly is still kept whole, which is what this engine did before.

/// Whether `entry` is the `border-image` shorthand. The table has no name to
/// match on by the time `join` sees an entry, and its five longhands are a
/// shape no other shorthand shares.
fn isBorderImage(entry: Shorthand) bool {
    return entry.kind == .unmodelled and
        entry.longhands.len == 5 and
        std.mem.eql(u8, entry.longhands[0], "border-image-source");
}

/// `border-image` as Chrome writes it, given its five longhands in table order.
/// Measured with tools/fingerprint/probes/expr-border-image-serialize.js: the
/// four components after the source are written only when at least one of them
/// is off its initial value, and then all four are, slashes and all --
/// `border-image-slice: 30` alone reads back `url("a") 30 / 1 / 0 stretch`.
/// With all four initial only the source is written, whatever the author
/// spelled: `border-image: url(a) 100%` comes back `url("a")`.
fn borderImageJoin(arena: Allocator, values: []const []const u8) ![]const u8 {
    for (values[1..], 1..) |held, i| {
        const initial = chrome_initial_values.initial.get(border_image_longhands[i]) orelse return "";
        if (!std.ascii.eqlIgnoreCase(held, initial)) {
            return std.mem.concat(arena, u8, &.{
                values[0], " ", values[1], " / ", values[2], " / ", values[3], " ", values[4],
            });
        }
    }
    return values[0];
}

const border_image_longhands = [_][]const u8{
    "border-image-source",
    "border-image-slice",
    "border-image-width",
    "border-image-outset",
    "border-image-repeat",
};

// --- the corner grammar -------------------------------------------------

/// `border-radius` is the one four-value box shorthand carrying a `/`, and the
/// `/` is what makes it its own kind: it is two box lists, one of horizontal
/// radii and one of vertical, distributed over four corner longhands that each
/// hold a *pair*. Measured by tools/fingerprint/probes/probe-css16.js.
fn cornersExpand(arena: Allocator, entry: Shorthand, value: []const u8) !?Expansion {
    var sides: [2][4][]const u8 = undefined;
    var written: [2]usize = .{ 0, 0 };
    var half: usize = 0;
    var walk = Components{ .text = std.mem.trim(u8, value, &std.ascii.whitespace), .slash = true };
    while (walk.next()) |component| {
        if (component.len == 1 and component[0] == '/') {
            // A second `/`, and one with nothing before it, are both declines.
            if (half == 1 or written[0] == 0) return null;
            half = 1;
            continue;
        }
        // A radius is a length or a percentage and nothing else, so `auto`,
        // `none` and a bare number are declines rather than four invented
        // corners. All four longhands take the same classes, measured, which is
        // why the first stands for the lot.
        if (!accepts(entry.longhands[0], component)) return null;
        if (written[half] == sides[half].len) return null;
        sides[half][written[half]] = component;
        written[half] += 1;
    }
    if (!walk.exhausted()) return null;
    // A `/` with nothing after it is a decline too.
    if (written[0] == 0 or (half == 1 and written[1] == 0)) return null;

    // The legacy WebKit spelling reads *exactly* two components as
    // horizontal-then-vertical rather than top-left-then-top-right, which is
    // the one place the two parsers disagree: `-webkit-border-radius: 10px
    // 20px` is `10px / 20px` where `border-radius: 10px 20px` is itself.
    if (half == 0 and entry.legacy_pair and written[0] == 2) {
        sides[1][0] = sides[0][1];
        written = .{ 1, 1 };
        half = 1;
    }

    const horizontal = boxRule(sides[0][0..written[0]], 4) orelse return null;
    const vertical = if (half == 0)
        horizontal
    else
        boxRule(sides[1][0..written[1]], 4) orelse return null;

    const values = try arena.alloc([]const u8, entry.longhands.len);
    if (values.len != horizontal.len) return null;
    for (values, 0..) |*out, i| {
        // A corner holds the pair, folded to one when the two agree -- which is
        // why a value with no `/` leaves every corner holding one component.
        out.* = if (std.ascii.eqlIgnoreCase(horizontal[i], vertical[i]))
            horizontal[i]
        else
            try std.mem.join(arena, " ", &.{ horizontal[i], vertical[i] });
    }
    return .{ .names = entry.longhands, .values = values };
}

/// What reading a corner shorthand back answers. Each list is elided by the box
/// rule *independently*, and the `/` goes only when the two come out identical:
/// `10px 20px / 10px 20px` reads `10px 20px` where `10px 10px / 20px 20px`
/// reads `10px / 20px`.
fn cornersJoin(arena: Allocator, values: []const []const u8) ![]const u8 {
    var horizontal: [4][]const u8 = undefined;
    var vertical: [4][]const u8 = undefined;
    if (values.len != horizontal.len) return "";
    for (values, 0..) |held, i| {
        var walk = Components.init(held);
        const first = walk.next() orelse return "";
        const second = walk.next() orelse first;
        // A corner holding anything but one component or two cannot have come
        // from this shorthand, so it cannot be written as one either.
        if (walk.next() != null or !walk.exhausted()) return "";
        horizontal[i] = first;
        vertical[i] = second;
    }

    const across = try std.mem.join(arena, " ", boxForm(&horizontal));
    const down = try std.mem.join(arena, " ", boxForm(&vertical));
    if (std.ascii.eqlIgnoreCase(across, down)) return across;
    return std.mem.concat(arena, u8, &.{ across, " / ", down });
}

// --- the layer grammar --------------------------------------------------

/// `background` is not a run of components. It is a comma-separated list of
/// layers, and inside a layer one position fills *two* longhands out of one to
/// four components, a `/` introduces a size and may only sit straight after
/// the position, one box component lands on both the origin and the clip, and
/// the colour belongs to the whole value rather than to a layer -- which is why
/// `background: red, blue` does not parse and `url(a), red` does. Every part of
/// that was measured; see chrome_shorthands.zig.
fn layerExpand(arena: Allocator, entry: Shorthand, value: []const u8) !?Expansion {
    const total = entry.longhands.len;
    const width = entry.layer_width;

    var texts: std.ArrayList([]const u8) = .empty;
    defer texts.deinit(arena);
    var split = Layers.init(value);
    while (split.next()) |layer| {
        if (layer.len == 0) return null;
        try texts.append(arena, layer);
    }
    if (texts.items.len == 0) return null;

    var layers: std.ArrayList([]const ?[]const u8) = .empty;
    defer layers.deinit(arena);
    for (texts.items, 0..) |text, n| {
        const last = n == texts.items.len - 1;
        const parsed = try parseLayer(arena, entry, text, last) orelse return null;
        // A shared slot is the whole value's, so only the last layer may reach
        // one: `url(a) blue, url(b)` does not parse where `url(a), url(b) blue`
        // does.
        if (!last) {
            for (parsed[width..]) |held| {
                if (held != null) return null;
            }
        }
        try layers.append(arena, parsed);
    }

    const values = try arena.alloc([]const u8, total);
    for (values, 0..) |*out, s| {
        if (s >= width) {
            out.* = layers.items[layers.items.len - 1][s] orelse entry.fillers[s];
            continue;
        }
        var list: std.ArrayList([]const u8) = .empty;
        defer list.deinit(arena);
        for (layers.items) |layer| {
            try list.append(arena, layer[s] orelse entry.fillers[s]);
        }
        out.* = try std.mem.join(arena, ", ", list.items);
    }
    return .{ .names = entry.longhands, .values = values };
}

/// One layer's components distributed over the slots, `null` where the value
/// never mentioned one, or null for the whole layer when it does not fit -- in
/// which case the caller keeps the declaration whole.
fn parseLayer(arena: Allocator, entry: Shorthand, text: []const u8, last: bool) !?[]?[]const u8 {
    const slots = try arena.alloc(?[]const u8, entry.longhands.len);
    @memset(slots, null);

    var found: std.ArrayList([]const u8) = .empty;
    defer found.deinit(arena);
    var walk = Components{ .text = std.mem.trim(u8, text, &std.ascii.whitespace), .slash = true };
    while (walk.next()) |component| try found.append(arena, component);
    if (!walk.exhausted()) return null;
    const toks = found.items;

    const axes = entry.axes;
    var i: usize = 0;
    var after_position = false;
    var mirrored = false;
    while (i < toks.len) {
        const token = toks[i];
        for (entry.refuse) |bad| {
            if (std.ascii.eqlIgnoreCase(bad, token)) return null;
        }
        if (token.len == 1 and token[0] == '/') {
            // The size is one of the two slots that take a pair, so
            // `left top / 10px 20px` is a layer and not a decline. The pair
            // goes to the longhand whole and is shortened there.
            if (!after_position or entry.size_slot == table.no_slot) return null;
            if (slots[entry.size_slot] != null) return null;
            const run = runLength(entry, toks[i + 1 ..], entry.size_slot);
            if (run == 0) return null;
            slots[entry.size_slot] = try runText(arena, toks[i + 1 ..], run);
            i += 1 + run;
            after_position = false;
            continue;
        }
        // The box pair. One component fills both -- `background: padding-box`
        // moves the origin *and* the clip -- and a second takes the clip over.
        // `text` is a clip and not an origin, which is why `text border-box`
        // lands the other way round from how it was written.
        if (entry.boxes[0] != table.no_slot and boxToken(entry, token)) {
            const first = entry.boxes[0];
            const second = entry.boxes[1];
            if (slots[first] == null and accepts(entry.longhands[first], token)) {
                slots[first] = token;
                if (slots[second] == null) {
                    slots[second] = token;
                    mirrored = true;
                }
            } else if (accepts(entry.longhands[second], token) and
                (slots[second] == null or mirrored))
            {
                slots[second] = token;
                mirrored = false;
            } else return null;
            after_position = false;
            i += 1;
            continue;
        }
        if (axes[0] != table.no_slot and slots[axes[0]] == null and slots[axes[1]] == null) {
            // Up to four components, longest first: `left 10px top 20px` is one
            // position where `left 10px no-repeat` is a two-component one
            // followed by a repeat.
            var room: usize = 0;
            while (i + room < toks.len and !(toks[i + room].len == 1 and toks[i + room][0] == '/')) {
                room += 1;
            }
            var k = @min(@as(usize, 4), room);
            const placed = while (k >= 1) : (k -= 1) {
                var pair: [2][]const u8 = undefined;
                if (try positionSlots(arena, entry, toks[i .. i + k], &pair)) {
                    slots[axes[0]] = pair[0];
                    slots[axes[1]] = pair[1];
                    break true;
                }
            } else false;
            if (placed) {
                i += k;
                after_position = true;
                continue;
            }
        }
        const order = entry.longhands.len;
        var slot: usize = 0;
        const placed = while (slot < order) : (slot += 1) {
            if (slots[slot] != null) continue;
            if (slot == axes[0] or slot == axes[1]) continue;
            if (slot == entry.boxes[0] or slot == entry.boxes[1]) continue;
            if (slot == entry.size_slot) continue;
            if (slot >= entry.layer_width and !last) continue;
            // The repeat is the other slot that takes a pair, which is what
            // makes `repeat no-repeat` one component of the layer rather than
            // two the model has nowhere to put.
            const run = runLength(entry, toks[i..], slot);
            if (run == 0) continue;
            slots[slot] = try runText(arena, toks[i..], run);
            break run;
        } else 0;
        if (placed == 0) return null;
        after_position = false;
        i += placed;
    }
    return slots;
}

/// How many of the components at the head of `toks` the slot takes as one
/// value: two where the table measured the longhand keeping a pair, one
/// everywhere else, and zero when the slot will not take even the first.
fn runLength(entry: Shorthand, toks: []const []const u8, slot: usize) usize {
    if (toks.len == 0 or isSlash(toks[0])) return 0;
    if (!accepts(entry.longhands[slot], toks[0])) return 0;
    if (toks.len < 2 or isSlash(toks[1])) return 1;
    if (std.mem.indexOfScalar(u8, entry.pairs, @intCast(slot)) == null) return 1;
    if (!accepts(entry.longhands[slot], toks[1])) return 1;
    return 2;
}

fn runText(arena: Allocator, toks: []const []const u8, run: usize) ![]const u8 {
    if (run == 1) return toks[0];
    return std.mem.join(arena, " ", toks[0..run]);
}

fn isSlash(token: []const u8) bool {
    return token.len == 1 and token[0] == '/';
}

/// Whether a component belongs to the box pair at all, which is what keeps a
/// keyword only the clip takes from being handed to the generic placement.
fn boxToken(entry: Shorthand, token: []const u8) bool {
    return accepts(entry.longhands[entry.boxes[0]], token) or
        accepts(entry.longhands[entry.boxes[1]], token);
}

/// The two values a position leaves on its axes. One component fills both --
/// the axis the page did not write is left holding `implied` -- two keywords
/// may come in either order where a length fixes it, and three or four
/// components are two `edge [offset]` groups.
fn positionSlots(
    arena: Allocator,
    entry: Shorthand,
    toks: []const []const u8,
    out: *[2][]const u8,
) !bool {
    const x = entry.longhands[entry.axes[0]];
    const y = entry.longhands[entry.axes[1]];
    if (toks.len == 1) {
        const takes_x = accepts(x, toks[0]);
        const takes_y = accepts(y, toks[0]);
        if (!takes_x and !takes_y) return false;
        out.* = if (!takes_x) .{ entry.implied, toks[0] } else .{ toks[0], entry.implied };
        return true;
    }
    if (toks.len == 2) {
        const first = toks[0];
        const second = toks[1];
        // `top right` is x=right y=top, and `10px left` does not parse: only
        // two keywords may swap.
        if (classify(first).identifier and classify(second).identifier) {
            const swap = (accepts(y, first) and !accepts(x, first)) or
                (accepts(x, second) and !accepts(y, second));
            if (swap) {
                if (!accepts(x, second) or !accepts(y, first)) return false;
                out.* = .{ second, first };
                return true;
            }
        }
        if (!accepts(x, first) or !accepts(y, second)) return false;
        out.* = .{ first, second };
        return true;
    }
    if (toks.len > 4) return false;
    const splits: [2][2]usize = if (toks.len == 3) .{ .{ 1, 2 }, .{ 2, 1 } } else .{ .{ 2, 2 }, .{ 0, 0 } };
    for (splits) |split| {
        if (split[0] + split[1] != toks.len) continue;
        var group: [2][]const u8 = undefined;
        var axis: [2]u8 = undefined;
        var ok = true;
        for (0..2) |g| {
            const start = if (g == 0) 0 else split[0];
            const run = toks[start .. start + split[g]];
            if (run.len == 1) {
                group[g] = run[0];
                const takes_x = accepts(x, run[0]);
                const takes_y = accepts(y, run[0]);
                axis[g] = if (takes_x and takes_y) 2 else if (takes_x) 0 else if (takes_y) 1 else 3;
            } else {
                // An offset may only follow an edge measured carrying one:
                // `left 10px` is a position and `center 10px` is not, which is
                // why `center 10px top` does not parse.
                const offset = classify(run[1]);
                if (!offset.length and !offset.percent) {
                    ok = false;
                    break;
                }
                group[g] = try std.mem.join(arena, " ", run);
                const takes_x = listed(entry.offsets[0], run[0]);
                const takes_y = listed(entry.offsets[1], run[0]);
                axis[g] = if (takes_x and takes_y) 2 else if (takes_x) 0 else if (takes_y) 1 else 3;
            }
            if (axis[g] == 3) {
                ok = false;
                break;
            }
        }
        if (!ok) continue;
        if (axis[0] == 0 and axis[1] != 0) {
            out.* = .{ group[0], group[1] };
        } else if (axis[0] == 1 and axis[1] != 1) {
            out.* = .{ group[1], group[0] };
        } else if (axis[0] == 2 and axis[1] == 1) {
            out.* = .{ group[0], group[1] };
        } else if (axis[0] == 2 and axis[1] == 0) {
            out.* = .{ group[1], group[0] };
        } else continue;
        return true;
    }
    return false;
}

fn listed(names: []const []const u8, token: []const u8) bool {
    for (names) |name| {
        if (std.ascii.eqlIgnoreCase(name, token)) return true;
    }
    return false;
}

/// Reading a layered shorthand back: every slot that is not at its dropped
/// value, in the order Chrome writes them, with the size behind a `/` and the
/// shared slots appended to the last layer.
fn layerJoin(arena: Allocator, entry: Shorthand, values: []const []const u8) ![]const u8 {
    const total = entry.longhands.len;
    const width = entry.layer_width;

    const lists = try arena.alloc([]const []const u8, total);
    var count: usize = 1;
    for (lists, values, 0..) |*list, value, s| {
        if (s >= width) {
            list.* = &.{value};
            continue;
        }
        var held: std.ArrayList([]const u8) = .empty;
        defer held.deinit(arena);
        var split = Layers.init(value);
        while (split.next()) |layer| try held.append(arena, layer);
        list.* = try held.toOwnedSlice(arena);
        count = @max(count, list.*.len);
    }

    var written: std.ArrayList([]const u8) = .empty;
    defer written.deinit(arena);
    for (0..count) |n| {
        var kept: std.ArrayList([]const u8) = .empty;
        defer kept.deinit(arena);
        for (0..total) |i| {
            const s = if (entry.order.len > 0) entry.order[i] else i;
            // A collapsing box pair is written as a unit, and `mask` is the
            // reason the flag exists: with the two agreeing it writes one
            // component where `background` writes both, and with the origin at
            // its initial it writes it anyway -- unless the clip holds a value
            // the origin could not take, which is why `mask: border-box
            // no-clip` answers just `no-clip`.
            if (entry.box_collapse and s == entry.boxes[1]) continue;
            if (entry.box_collapse and s == entry.boxes[0]) {
                const origin = layerAt(lists[entry.boxes[0]], entry, entry.boxes[0], n, count) orelse continue;
                const clip = layerAt(lists[entry.boxes[1]], entry, entry.boxes[1], n, count) orelse continue;
                const bare_origin = dropped(entry.omit[entry.boxes[0]], origin);
                const one = if (bare_origin) entry.fillers[entry.boxes[0]] else origin;
                const other = if (dropped(entry.omit[entry.boxes[1]], clip))
                    entry.fillers[entry.boxes[1]]
                else
                    clip;
                if (std.ascii.eqlIgnoreCase(one, other)) {
                    if (!bare_origin) try kept.append(arena, one);
                } else if (bare_origin and !accepts(entry.longhands[entry.boxes[0]], other)) {
                    try kept.append(arena, other);
                } else {
                    try kept.append(arena, one);
                    try kept.append(arena, other);
                }
                continue;
            }
            const held = layerAt(lists[s], entry, s, n, count) orelse continue;
            if (dropped(entry.omit[s], held)) continue;
            if (s == entry.size_slot) try kept.append(arena, "/");
            try kept.append(arena, held);
        }
        if (kept.items.len == 0) {
            try written.append(arena, entry.empty orelse "");
            continue;
        }
        try written.append(arena, try std.mem.join(arena, " ", kept.items));
    }
    return std.mem.join(arena, ", ", written.items);
}

/// What one slot holds in layer `n`: a shared slot only in the last layer, and
/// nothing at all where a longhand's list is shorter than the layer count --
/// measured, a `background-image` with two layers over a one-layer position
/// leaves the second layer's position unwritten rather than repeating it.
fn layerAt(
    list: []const []const u8,
    entry: Shorthand,
    slot: usize,
    n: usize,
    count: usize,
) ?[]const u8 {
    if (slot >= entry.layer_width) {
        return if (n == count - 1) list[0] else null;
    }
    return if (n < list.len) list[n] else null;
}

/// A value's layers: top-level commas separate, parentheses and quotes hold.
pub const Layers = struct {
    text: []const u8,
    index: usize = 0,

    pub fn init(text: []const u8) Layers {
        return .{ .text = std.mem.trim(u8, text, &std.ascii.whitespace) };
    }

    pub fn next(self: *Layers) ?[]const u8 {
        if (self.index > self.text.len) return null;
        const start = self.index;
        var depth: usize = 0;
        var quote: ?u8 = null;
        while (self.index < self.text.len) : (self.index += 1) {
            const c = self.text[self.index];
            if (quote) |q| {
                if (c == q) quote = null;
                continue;
            }
            switch (c) {
                '"', '\'' => quote = c,
                '(' => depth += 1,
                ')' => depth -|= 1,
                ',' => if (depth == 0) {
                    const out = self.text[start..self.index];
                    self.index += 1;
                    return std.mem.trim(u8, out, &std.ascii.whitespace);
                },
                else => {},
            }
        }
        const out = self.text[start..self.index];
        self.index += 1;
        return std.mem.trim(u8, out, &std.ascii.whitespace);
    }
};

// --- the grammar --------------------------------------------------------

/// The widest group any measured shorthand has, so the slots fit on the stack.
const max_group = 8;

fn slotOf(entry: Shorthand, index: usize) usize {
    return if (entry.blocked) index / entry.groups else index % entry.group;
}

/// The longhand standing for a component slot: the first of its block when the
/// repeats are blocked (`border`'s four widths), the slot itself otherwise.
fn representative(entry: Shorthand, slot: usize) usize {
    return if (entry.blocked) slot * entry.groups else slot;
}

/// Which slot a component goes to: the first one still empty that accepts it.
/// Position is not the test -- `1px solid red`, `solid red 1px` and
/// `red 1px solid` all land identically, measured.
fn place(entry: Shorthand, component: []const u8, slots: []const []const u8) ?usize {
    for (slots, 0..) |held, slot| {
        if (held.len > 0) continue;
        if (!accepts(entry.longhands[representative(entry, slot)], component)) continue;
        return slot;
    }
    return null;
}

fn accepts(longhand: []const u8, component: []const u8) bool {
    const classes = classify(component);
    if (classes.identifier) {
        if (chrome_keywords.keywords.get(longhand)) |known| {
            for (known) |keyword| {
                if (std.ascii.eqlIgnoreCase(keyword, component)) return true;
            }
        }
    }
    // An easing written as a function. The generator measured both
    // timing-function longhands as taking no value class at all -- the class
    // vocabulary has no name for an easing -- so `cubic-bezier()` matched
    // nothing below, `place` found it no slot, and the whole shorthand declined
    // and was kept as the author wrote it. That is why `animation: a 1s
    // cubic-bezier(...)` did not expand where `animation: a 1s linear` did.
    // Measured with tools/fingerprint/probes/expr-animation-serialize.js.
    if (isEasingFunction(component) and isTimingFunction(longhand)) {
        return true;
    }

    const taken = valueClasses(longhand);
    for (taken) |class| {
        if (switch (class) {
            .length => classes.length,
            .percent => classes.percent,
            .number => classes.number,
            .angle => classes.angle,
            .time => classes.time,
            .url => classes.url,
            .string => classes.string,
            .identifier => classes.identifier,
            .colour => classes.colour,
            .function => classes.function,
            .gradient => classes.gradient,
            .image => classes.image,
        }) return true;
    }
    return false;
}

// -- refusing a declaration --------------------------------------------------
//
// Everything above answers what a value *becomes*. This answers whether it
// becomes anything at all: Chrome throws a declaration it cannot parse away,
// where this engine's only other answer is to keep it whole. Measured over 525
// readings by tools/fingerprint/probes/probe-css17.js.
//
// The whole of it is conservative in one direction, deliberately. Keeping a
// declaration Chrome refused is the reading this engine already gave before any
// of this existed -- wrong, but wrong in a way pages survive. Refusing one
// Chrome kept is a new kind of wrong: the page loses a style it was written
// with. So every test here is a licence to refuse rather than a requirement to
// accept, and anything it cannot judge is kept.

/// Whether Chrome throws a *longhand* declaration away. Two independent tests,
/// measured: the value classes the property takes (`accepts`), and the range it
/// takes them in (`chrome_bounds`, which the classes cannot see -- `-10px` and
/// `10px` are both a `<length>` and `margin` takes one where `padding` does not).
pub fn refusesLonghand(name: []const u8, value: []const u8) bool {
    if (!judgeable(value)) return false;
    if (cssWide(std.mem.trim(u8, value, &std.ascii.whitespace)) != null) return false;

    // The grammar half is only asked of a property the generator measured a
    // value class for. A keyword-only longhand has an empty class list, so
    // `accepts` there is the keyword table alone, and a keyword missing from it
    // would read as a refusal rather than as the gap it is.
    const graded_name = gradedName(name);
    const classes = valueClasses(graded_name);
    const graded = classes.len > 0;

    var components = slashComponents(value);
    while (components.next()) |component| {
        if (outOfBounds(name, component)) return true;
        if (graded and !accepts(graded_name, component)) return true;
    }
    return false;
}

/// The name whose measured grammar answers for this one. Only the four logical
/// corner spellings need it: `border-radius` expands to the *physical* four, so
/// no shorthand has ever handed the generator a `border-start-start-radius` and
/// neither the class table nor the keyword table has heard of it. Measured
/// (probe-css16, probe-css17): a logical corner takes and refuses exactly what
/// the physical one does, which is what makes standing in for it honest.
/// The value classes a longhand takes, measured. An empty answer means "not
/// measured", which reads the same as "matches nothing" at both call sites.
///
/// `chrome_shorthands.value_classes` is generated by walking the longhands of
/// the shorthands the generator probes, so a longhand nothing expands to never
/// got measured and has no entry -- and no entry means `refusesLonghand` skips
/// its grammar check entirely. `color` is one of those: nothing expands to it,
/// so `color: FakeColor` was stored here where Chrome drops the declaration.
/// Kasada plants exactly that identifier at x-hyatt and reads the computed
/// value back (tools/fingerprint/results/b55-answers-lp.json), which makes the
/// gap a tell rather than a rounding error.
///
/// Measured with tools/fingerprint/probes/expr-b55-color-classes.js on the
/// generator's own token battery, so the answer is in the same vocabulary:
/// `color` takes `#abc` and `rgb(1, 2, 3)` and refuses the other ten, which is
/// the pair the generator wrote for `background-color`.
///
/// Sixteen further colour longhands have the same gap -- `caret-color`,
/// `accent-color`, `fill`, `stroke`, `flood-color`, `stop-color`,
/// `-webkit-text-fill-color` and the logical border-colour spellings among
/// them. They are deliberately not here: grading a property whose keyword table
/// is short of one real keyword turns a valid declaration into a dropped one,
/// so each needs its own measurement rather than `color`'s answer copied
/// across. `color`'s keyword table is the whole colour list plus
/// `currentcolor`, which is what makes grading it safe.
///
/// The return type is deliberately not optional. Writing it `?[]const
/// table.Class` and answering `null` here crashes the Zig 0.16 backend with a
/// SIGSEGV in `build-exe`, reproducibly: adding the `?` fails the build and
/// taking it away builds clean, with nothing else changed.
const color_classes = [_]table.Class{ .colour, .function };

fn valueClasses(longhand: []const u8) []const table.Class {
    if (table.value_classes.get(longhand)) |classes| return classes;
    if (std.mem.eql(u8, longhand, "color")) return &color_classes;
    return &.{};
}

fn gradedName(name: []const u8) []const u8 {
    const logical = std.StaticStringMap([]const u8).initComptime(.{
        .{ "border-start-start-radius", "border-top-left-radius" },
        .{ "border-start-end-radius", "border-top-right-radius" },
        .{ "border-end-start-radius", "border-bottom-left-radius" },
        .{ "border-end-end-radius", "border-bottom-right-radius" },
    });
    return logical.get(name) orelse name;
}

/// The value's components with the `/` among them rather than stopping at it.
/// Every model above stops, because a `/` is a shorthand's punctuation and none
/// of them has a use for one; a refusal test wants the opposite, since a `/` no
/// class accepts is exactly the sort of thing Chrome throws the declaration
/// away for -- `border-top-left-radius: 10px / 20px`, measured.
pub fn slashComponents(value: []const u8) Components {
    var components = Components.init(value);
    components.slash = true;
    return components;
}

/// Whether a shorthand `expand` declined is Chrome's refusal rather than this
/// engine's retreat. `expand` answers null for both and the difference is the
/// whole point: a `.layers` or `.components` model is licenced to decline a row
/// Chrome accepts, so only the two kinds whose decline *is* a grammar failure
/// are read as one -- a box that was handed five components, and a corner list
/// whose slashes do not work out.
pub fn refusesDeclined(entry: Shorthand, value: []const u8) bool {
    switch (entry.kind) {
        .box4, .box2, .corners => {},
        else => return false,
    }
    if (cssWide(std.mem.trim(u8, value, &std.ascii.whitespace)) != null) return false;
    return judgeable(value);
}

/// Whether this engine can say anything about the value at all. It cannot when
/// a component is a function whose name `classify` does not know -- `calc()` is
/// the live one, because Chrome evaluates it and this engine substitutes it, so
/// neither the class nor the sign of what it holds is visible from here. Nor
/// when the value carries a comma: a comma-separated list is a grammar nothing
/// in this file models, and splitting it on whitespace would judge `Arial,` as
/// a malformed identifier.
fn judgeable(value: []const u8) bool {
    if (std.mem.indexOfScalar(u8, value, ',') != null) return false;
    // A comment. Chrome takes it out and keeps the declaration -- `margin: 10px
    // /* c */ 20px` is `10px 20px` -- and nothing here removes one, so the
    // components would come back as punctuation no class accepts.
    if (std.mem.indexOf(u8, value, "/*") != null) return false;
    var components = slashComponents(value);
    while (components.next()) |component| {
        if (component.len == 0 or component[component.len - 1] != ')') continue;
        const open = std.mem.indexOfScalar(u8, component, '(') orelse continue;
        if (!hasClass(functionClass(component[0..open]))) return false;
    }
    return components.exhausted();
}

/// Whether the component is outside the range the property takes them in.
fn outOfBounds(property: []const u8, component: []const u8) bool {
    if (unknownUnit(component)) return true;
    const classes = classify(component);
    if (classes.percent and chrome_bounds.no_percent.has(property)) return true;
    if (classes.number and outsideNumberRange(property, component)) return true;
    if (!classes.length and !classes.percent and !classes.number and
        !classes.angle and !classes.time) return false;
    if (!negative(component)) return false;
    return chrome_bounds.no_negative.has(property);
}

/// Whether the component is a number carrying a run of letters no unit spells.
/// `classify` reads any of them as a unit and answers `<length>`, which is the
/// right guess for placing a component and the wrong one for judging it: there
/// is no property `10foo` belongs to, so this is asked of every property rather
/// than of the ones with a measured class list.
///
/// The lookup folds case, because `10PX` is `10px`. A spelling longer than
/// anything in the table is answered without folding it anywhere.
fn unknownUnit(component: []const u8) bool {
    const digits = numberEnd(component);
    if (digits == 0) return false;
    const unit = component[digits..];
    if (unit.len == 0) return false;
    // A `%` is not a unit spelling and has its own class; anything else with a
    // non-letter in it classified as nothing before this existed and still does.
    for (unit) |c| {
        if (!std.ascii.isAlphabetic(c)) return false;
    }
    if (unit.len > chrome_units.longest) return true;
    var folded: [chrome_units.longest]u8 = undefined;
    for (unit, 0..) |c, i| folded[i] = std.ascii.toLower(c);
    return !chrome_units.units.has(folded[0..unit.len]);
}

/// Whether a bare number is one this property does not take: outside a bound
/// that was measured and bisected, a fraction where only whole numbers go, or a
/// bare number at all where the property wants a unit on one. That last test
/// belongs here rather than with the value classes because a unitless zero is a
/// `<length>` as much as it is a number, so the classes wave it through --
/// `rotate: 0` and `overflow-clip-margin: 0` are refused where `0deg` and `0px`
/// are kept, measured.
///
/// A number this cannot read is not a number this refuses. The bounds are a
/// licence to throw a declaration away and nothing here is allowed to guess.
fn outsideNumberRange(property: []const u8, component: []const u8) bool {
    if (chrome_bounds.needs_unit.has(property)) return true;
    const range = chrome_bounds.number_range.get(property) orelse return false;
    const value = std.fmt.parseFloat(f64, component) catch return false;
    if (range.min) |min| if (value < min) return true;
    if (range.max) |max| if (value > max) return true;
    return range.integer and @floor(value) != value;
}

/// A leading minus is not a negative number. `padding: -0px` is accepted
/// everywhere `0px` is and reads back with the sign dropped, measured -- and so
/// a property name that happens to start with one (`-webkit-fill-available`) is
/// not a number at all, which `numberEnd` answering 0 already says.
fn negative(component: []const u8) bool {
    if (component.len == 0 or component[0] != '-') return false;
    return !isZero(component[0..numberEnd(component)]);
}

fn hasClass(classes: Classes) bool {
    return classes.length or classes.percent or classes.number or classes.angle or
        classes.time or classes.url or classes.string or classes.identifier or
        classes.colour or classes.function or classes.gradient or classes.image;
}

const Classes = packed struct {
    length: bool = false,
    percent: bool = false,
    number: bool = false,
    angle: bool = false,
    time: bool = false,
    url: bool = false,
    string: bool = false,
    identifier: bool = false,
    colour: bool = false,
    function: bool = false,
    gradient: bool = false,
    image: bool = false,
};

/// A component's value classes, by shape alone -- the same test the generator
/// simulated before writing any of these tables down. A token can be in two:
/// a unitless zero is a `<length>` as well as a `<number>`, which is why
/// `border-top: 0` reaches the width.
fn classify(component: []const u8) Classes {
    if (component.len == 0) return .{};
    if (component[0] == '"' or component[0] == '\'') return .{ .string = true };
    if (component[0] == '#') {
        for (component[1..]) |c| {
            if (!std.ascii.isHex(c)) return .{};
        }
        return .{ .colour = true };
    }
    if (component[component.len - 1] == ')') {
        const open = std.mem.indexOfScalar(u8, component, '(') orelse return .{};
        return functionClass(component[0..open]);
    }
    const digits = numberEnd(component);
    if (digits == 0) {
        for (component, 0..) |c, i| {
            const ok = std.ascii.isAlphabetic(c) or c == '-' or c == '_' or
                (i > 0 and std.ascii.isDigit(c));
            if (!ok) return .{};
        }
        return .{ .identifier = true };
    }
    const unit = component[digits..];
    if (unit.len == 0) {
        return if (isZero(component)) .{ .length = true, .number = true } else .{ .number = true };
    }
    if (std.mem.eql(u8, unit, "%")) return .{ .percent = true };
    for ([_][]const u8{ "deg", "grad", "rad", "turn" }) |angle| {
        if (std.ascii.eqlIgnoreCase(unit, angle)) return .{ .angle = true };
    }
    for ([_][]const u8{ "s", "ms" }) |time| {
        if (std.ascii.eqlIgnoreCase(unit, time)) return .{ .time = true };
    }
    for (unit) |c| {
        if (!std.ascii.isAlphabetic(c)) return .{};
    }
    return .{ .length = true };
}

/// A function's class comes from its name rather than from the fact that it is
/// a function: `background-image` takes `linear-gradient()` and not `rgb()`, and
/// `background-color` the other way round, so a single `function` class puts a
/// gradient in the colour. A name this does not know has no class at all, and a
/// value carrying one is declined rather than guessed at.
fn functionClass(name: []const u8) Classes {
    if (std.ascii.eqlIgnoreCase(name, "url")) return .{ .url = true };
    if (std.ascii.endsWithIgnoreCase(name, "-gradient")) return .{ .gradient = true };
    if (std.ascii.eqlIgnoreCase(name, "image-set") or
        std.ascii.eqlIgnoreCase(name, "-webkit-image-set"))
    {
        return .{ .image = true };
    }
    for ([_][]const u8{
        "rgb",       "rgba",       "hsl",   "hsla",  "hwb",
        "lab",       "lch",        "oklab", "oklch", "color",
        "color-mix", "light-dark",
    }) |known| {
        if (std.ascii.eqlIgnoreCase(name, known)) return .{ .function = true };
    }
    return .{};
}

/// The two longhands an easing lands in. Both were measured with an empty value
/// class list, so `accepts` has to name them rather than read them off a table.
fn isTimingFunction(longhand: []const u8) bool {
    return std.mem.eql(u8, longhand, "animation-timing-function") or
        std.mem.eql(u8, longhand, "transition-timing-function");
}

/// Whether the component is an `<easing-function>` written as a call. The three
/// names are the whole of the grammar; a bare `ease` or `linear` is an
/// identifier and reaches the keyword table instead.
fn isEasingFunction(component: []const u8) bool {
    if (component.len == 0 or component[component.len - 1] != ')') return false;
    const open = std.mem.indexOfScalar(u8, component, '(') orelse return false;
    const name = component[0..open];
    for ([_][]const u8{ "cubic-bezier", "steps", "linear" }) |known| {
        if (std.ascii.eqlIgnoreCase(name, known)) return true;
    }
    return false;
}

/// How much of the component is a number, 0 when it does not start with one.
fn numberEnd(component: []const u8) usize {
    var i: usize = 0;
    if (i < component.len and (component[i] == '+' or component[i] == '-')) i += 1;
    const start = i;
    while (i < component.len and std.ascii.isDigit(component[i])) i += 1;
    if (i < component.len and component[i] == '.') {
        i += 1;
        while (i < component.len and std.ascii.isDigit(component[i])) i += 1;
    }
    if (i == start) return 0;
    // An exponent. Chrome takes one and prints the result -- `margin: 1E1px` is
    // `10px` -- and without this the `E1px` reads as a unit with a digit in it,
    // so the component classifies as nothing and a refusal test would throw the
    // declaration away.
    if (i < component.len and (component[i] == 'e' or component[i] == 'E')) {
        var exp = i + 1;
        if (exp < component.len and (component[exp] == '+' or component[exp] == '-')) exp += 1;
        const digits = exp;
        while (exp < component.len and std.ascii.isDigit(component[exp])) exp += 1;
        if (exp > digits) i = exp;
    }
    return i;
}

fn isZero(component: []const u8) bool {
    for (component) |c| {
        if (c != '0' and c != '.' and c != '+' and c != '-') return false;
    }
    return true;
}

fn cssWide(value: []const u8) ?[]const u8 {
    for (chrome_keywords.css_wide) |keyword| {
        if (std.ascii.eqlIgnoreCase(keyword, value)) return keyword;
    }
    return null;
}

fn translated(entry: Shorthand, value: []const u8) []const u8 {
    for (entry.translate) |pair| {
        if (std.ascii.eqlIgnoreCase(pair[0], value)) return pair[1];
    }
    return value;
}

fn preset(entry: Shorthand, value: []const u8) ?@TypeOf(entry.presets[0]) {
    for (entry.presets) |row| {
        if (std.ascii.eqlIgnoreCase(row[0], value)) return row;
    }
    return null;
}

fn dropped(omit: []const []const u8, value: []const u8) bool {
    for (omit) |candidate| {
        if (std.ascii.eqlIgnoreCase(candidate, value)) return true;
    }
    return false;
}

/// The 1/2/3/4-value box rule: top, right, bottom, left -- or start and end for
/// the two-longhand ones.
fn boxRule(written: []const []const u8, width: usize) ?[4][]const u8 {
    if (written.len == 0 or written.len > width) return null;
    var out: [4][]const u8 = .{ "", "", "", "" };
    if (width == 2) {
        out[0] = written[0];
        out[1] = if (written.len == 1) written[0] else written[1];
        return out;
    }
    out[0] = written[0];
    out[1] = if (written.len > 1) written[1] else written[0];
    out[2] = if (written.len > 2) written[2] else written[0];
    out[3] = if (written.len > 3) written[3] else out[1];
    return out;
}

/// The shortest form the box rule writes back: `1px 1px 1px 1px` is `1px`, and
/// `1px 2px 3px 2px` is `1px 2px 3px`.
fn boxForm(values: []const []const u8) []const []const u8 {
    const eq = std.ascii.eqlIgnoreCase;
    if (values.len == 2) return if (eq(values[0], values[1])) values[0..1] else values;
    if (!eq(values[1], values[3])) return values;
    if (!eq(values[0], values[2])) return values[0..3];
    return if (eq(values[0], values[1])) values[0..1] else values[0..2];
}

/// A value's top-level components: whitespace separates, a parenthesised or
/// quoted run stays whole, and a `/` is a component of its own -- which is how
/// a value carrying one is rejected rather than mis-split.
pub const Components = struct {
    text: []const u8,
    index: usize = 0,
    stopped: bool = false,
    /// Whether a `/` comes back as a component of its own. The flat models have
    /// no use for one, so they stop there instead and their shorthand keeps the
    /// value whole.
    slash: bool = false,

    pub fn init(text: []const u8) Components {
        return .{ .text = std.mem.trim(u8, text, &std.ascii.whitespace) };
    }

    pub fn next(self: *Components) ?[]const u8 {
        while (self.index < self.text.len and std.ascii.isWhitespace(self.text[self.index])) {
            self.index += 1;
        }
        if (self.index >= self.text.len) return null;
        const start = self.index;
        if (self.text[start] == '/') {
            if (!self.slash) {
                self.stopped = true;
                return null;
            }
            self.index += 1;
            return self.text[start..self.index];
        }
        var depth: usize = 0;
        var quote: ?u8 = null;
        while (self.index < self.text.len) : (self.index += 1) {
            const c = self.text[self.index];
            if (quote) |q| {
                if (c == q) quote = null;
                continue;
            }
            switch (c) {
                '"', '\'' => quote = c,
                '(' => depth += 1,
                ')' => depth -|= 1,
                '/' => if (depth == 0) break,
                else => if (depth == 0 and std.ascii.isWhitespace(c)) break,
            }
        }
        return self.text[start..self.index];
    }

    /// Whether the whole value was consumed, rather than abandoned at a `/`.
    pub fn exhausted(self: *Components) bool {
        if (self.stopped) return false;
        while (self.index < self.text.len) : (self.index += 1) {
            if (!std.ascii.isWhitespace(self.text[self.index])) return false;
        }
        return true;
    }
};
